function renderIntersection(pair){
 const el=document.querySelector(".venn-center");el.replaceChildren();
 const key=pair?[pair.a,pair.b].sort().join("|"):null;
 const lines=pair?intersectionTerms[key][languageMode==="plain"?1:0]:[languageMode==="plain"?"Not written":"Not authored"];
 document.getElementById("venn-qualifier").textContent=lines.some(x=>x.includes("*"))?(languageMode==="plain"?"* These features depend on the presentation and are not required for both diagnoses. Read the full explanations below.":"* These are conditional features, not criteria required in both diagnoses. Refer to the full pair-specific explanation below."):"";
 const title=document.createElementNS(svgNS,"title");title.textContent=pair?pair.shared.join("; ")+". Possible features only; see full explanations below. Asterisks indicate features that are not required in both diagnoses.":"No authored overlap comparison for this pair.";el.append(title);
 lines.forEach((line,i)=>{const span=document.createElementNS(svgNS,"tspan");span.setAttribute("x","300");span.setAttribute("y",String(158+i*23));span.textContent=line;el.append(span);});
}
